package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.annotation.JsonIdentityInfo.Id;
import com.fasterxml.jackson.databind.annotation.JsonIdentityInfo;
import com.fasterxml.jackson.databind.introspect.ObjectIdInfo;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ObjectIdInfo constructor and getter methods.
 */
public class ObjectIdInfo_ObjectIdInfo_TriageGen2Test {

    // Mock classes to satisfy the generic constraints for Generator and Resolver
    public static class MockGenerator implements com.fasterxml.jackson.databind.util.IdGenerator<String> {
        @Override public String generate(com.fasterxml.jackson.databind.SerializerProvider provider) { return null; }
        @Override public void reset() {}
    }

    public static class MockResolver implements com.fasterxml.jackson.databind.annotation.JsonIdentityInfo.ObjectIdResolver {
        @Override public Object resolveId(com.fasterxml.jackson.databind.DatabindContext context, Object id) { return null; }
        @Override public com.fasterxml.jackson.databind.annotation.JsonIdentityInfo.ObjectIdGenerator getGenerator(com.fasterxml.jackson.databind.DatabindContext context, Object id) { return null; }
    }

    @Test
    public void testConstructorAndGetters() {
        // Arrange
        PropertyName name = PropertyName.construct("testId", false, null);
        Class<?> scope = Object.class;
        Class<? extends com.fasterxml.jackson.databind.util.IdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;

        // Act
        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Assert
        Assert.assertEquals(name, info.getPropertyName());
        Assert.assertEquals(scope, info.getScope());
        Assert.assertEquals(gen, info.getGeneratorType());
        Assert.assertEquals(resolver, info.getResolverType());
        Assert.assertFalse("alwaysAsId should be false by default in this constructor", info.getAlwaysAsId());
    }

    @Test
    public void testWithAlwaysAsId() {
        // Arrange
        PropertyName name = PropertyName.construct("testId", false, null);
        Class<?> scope = Object.class;
        Class<? extends com.fasterxml.jackson.databind.util.IdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;
        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Act & Assert
        ObjectIdInfo infoWithTrue = info.withAlwaysAsId(true);
        Assert.assertTrue(infoWithTrue.getAlwaysAsId());

        ObjectIdInfo infoWithFalse = infoWithTrue.withAlwaysAsId(false);
        Assert.assertFalse(infoWithFalse.getAlwaysAsId());
    }

    @Test
    public void testToString() {
        // Arrange
        PropertyName name = PropertyName.construct("testId", false, null);
        Class<?> scope = Object.class;
        Class<? extends com.fasterxml.jackson.databind.util.IdGenerator<?>> gen = MockGenerator.class;
        Class<? extends ObjectIdResolver> resolver = MockResolver.class;
        ObjectIdInfo info = new ObjectIdInfo(name, scope, gen, resolver);

        // Act
        String toStringResult = info.toString();

        // Assert
        Assert.assertNotNull(toStringResult);
        // Basic check to ensure it contains identifying information
        Assert.assertTrue(toStringResult.contains("testId"));
    }
}
